mapper.select:
/* OrderMapper.selectHubnBatchUpdateHoldTarget : 일괄변경 - 업데이트 대상 건 조회 */ SELECT od.OD_JOB_NO , od.HBL_NO , od.PO_NO , od.MBL_NO , hld.HOLD_CODE , hld.HOLD_RELEASE_YN
, od.ENT_CODE , od.BOUND , od.BOUND_TYPE , od.CONSIGNEE_NAME_LOC , od.CONSIGNEE_HP , od.CONSIGNEE_ZIPCODE , od.DELIVERY_CODE , od.CUST_CODE_LV1 , od.CUST_CODE_LV2 , od.CUST_CODE_LV3 , CASE WHEN od.CUST_CODE_LV3 IS NOT NULL THEN 3 WHEN od.CUST_CODE_LV2 IS NOT NULL THEN 2 ELSE 1 END AS STOCK_CUST_LV
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_PO_INFO poInfo ON poInfo.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_HOLD hld ON hld.OD_JOB_NO = od.OD_JOB_NO
AND hld.HOLD_CODE = #{holdCode}
WHERE (
(od.MASTER_OD_JOB_NO = #{item.odJobNo} AND ISNULL(ad.SIMPLE_DOC_NO, '') = ISNULL(CAST(#{item.simpleDocNo} AS VARCHAR(20)), ''))
)
WHERE od.MASTER_OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H'
WHERE od.OD_JOB_NO IN(#{item})

mapper.delete:
/* OrderMapper.deleteResetSendCustomsManifest : 목록신고초기화 */
DELETE FROM TB_ECM_POD_02
WHERE OD_JOB_NO IN(
#{item}
)
AND POD_STATUS IN('ECM110', 'ECM120', 'ECM130', 'ECM143');

DELETE FROM TB_ECM_POD_03
WHERE OD_JOB_NO IN(
#{item}
)
AND POD_STATUS = 'ECM220';
